"""Design verification for this hardware project, generated by rea-hardware.

Every gate is a pytest case. Gates read the real design files (KiCad schematic/PCB, KiCad-exported
3D board, enclosure STLs, fab outputs) and the scope contract in rea/spec.yaml. Expected values come
from the spec and the fab profile, never from the design under test. Do not edit: rea/tests.lock.json
pins this file, and the tests.integrity gate fails if it changes.
"""

import pytest

from rea_hardware.gates import REGISTRY, select

GATES = select()


@pytest.mark.parametrize("gate_id", GATES)
def test_gate(gate_id, gate_report):
    r = gate_report[gate_id]
    if r["status"] == "SKIP":
        pytest.skip("; ".join(f["message"] for f in r["findings"]) or "prerequisite missing")
    problems = [f"{f['message']}" + (f" @ {f['where']}" if f["where"] else "") for f in r["findings"] if f["severity"] == "error"]
    assert r["status"] in ("PASS", "WARN"), f"{gate_id} ({REGISTRY[gate_id][1]}): {r['status']}\n  - " + "\n  - ".join(problems[:25])
